import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface CreateApplicationRequest {
  type: 'photo' | 'video';
  reference_file_id: string;
  source_file_id: string;
}

export interface Application {
  id: string;
  type?: string;
  status: string;
  similarity_score?: number;
  verification_status?: string;
  result_file_ids?: string[];
  segments?: { start_time: number; end_time: number; result_file_id: string }[];
  created_at: string;
  updated_at?: string;
}

export interface UploadUrlResponse {
  file_id: string;
  upload_url: string;
  s3_key: string;
  expires_at: string;
}

@Injectable({ providedIn: 'root' })
export class ApiService {
  private http = inject(HttpClient);
  private baseUrl = '/api';

  createApplication(req: CreateApplicationRequest): Observable<Application> {
    return this.http.post<Application>(`${this.baseUrl}/applications`, req);
  }

  getApplication(id: string): Observable<Application> {
    return this.http.get<Application>(`${this.baseUrl}/applications/${id}`);
  }

  getUploadUrl(fileType: string, fileRole: string, sizeBytes: number): Observable<UploadUrlResponse> {
    return this.http.post<UploadUrlResponse>(`${this.baseUrl}/files/upload-url`, {
      file_type: fileType,
      file_role: fileRole,
      size_bytes: sizeBytes
    });
  }

  confirmFileUpload(id: string): Observable<{ file_id: string; status: string }> {
    return this.http.post(`${this.baseUrl}/files/${id}/confirm`, {});
  }

  triggerProcessing(id: string): Observable<{ application_id: string; job_id: string; status: string }> {
    return this.http.post(`${this.baseUrl}/applications/${id}/process`, {});
  }
}

import { Component, inject } from '@angular/core';
import { Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { MatButtonModule } from '@angular/material/button';
import { MatCardModule } from '@angular/material/card';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';

@Component({
  selector: 'app-scr-001',
  standalone: true,
  imports: [CommonModule, MatButtonModule, MatCardModule, MatProgressSpinnerModule],
  template: `
    <div class="scr-001">
      <div *ngIf="state === 'loading'" class="center">
        <mat-spinner></mat-spinner>
      </div>
      <div *ngIf="state === 'error'" class="center">
        <p>Ошибка инициализации</p>
        <button mat-button (click)="retry()">Повторить</button>
      </div>
      <div *ngIf="state === 'forbidden'" class="center">
        <p>Требуется авторизация</p>
        <button mat-button (click)="login()">Войти</button>
      </div>
      <div *ngIf="state === 'success' || state === 'empty'" class="cards">
        <mat-card class="card" (click)="select('photo')">
          <mat-card-title>Фотоотчет</mat-card-title>
          <mat-card-content>JPEG/PNG</mat-card-content>
        </mat-card>
        <mat-card class="card" (click)="select('video')">
          <mat-card-title>Видеопоток</mat-card-title>
          <mat-card-content>MP4 150–300 с</mat-card-content>
        </mat-card>
      </div>
    </div>
  `
})
export class Scr001Component {
  private router = inject(Router);
  state: 'empty' | 'loading' | 'error' | 'forbidden' | 'success' = 'loading';

  constructor() {
    setTimeout(() => this.state = 'success', 500);
  }

  retry() { this.state = 'loading'; setTimeout(() => this.state = 'success', 500); }
  login() { /* TODO: auth */ }
  select(type: string) { this.router.navigate(['/upload'], { queryParams: { type } }); }
}

import { Component, inject } from '@angular/core';
import { Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatCardModule } from '@angular/material/card';
import { ApiService } from '../../services/api.service';

@Component({
  selector: 'app-scr-002',
  standalone: true,
  imports: [CommonModule, FormsModule, MatButtonModule, MatProgressBarModule, MatCardModule],
  template: `
    <div class="scr-002">
      <div *ngIf="state === 'forbidden'" class="center">
        <p>Требуется авторизация</p>
        <button mat-button (click)="login()">Войти</button>
      </div>
      <div *ngIf="state !== 'forbidden'">
        <mat-card class="slot">
          <mat-card-title>Исходный файл</mat-card-title>
          <input type="file" (change)="onSourceFile($event)" />
          <mat-progress-bar *ngIf="sourceProgress > 0" [value]="sourceProgress"></mat-progress-bar>
          <p *ngIf="sourceError" class="error">{{ sourceError }}</p>
          <button mat-button *ngIf="sourceError" (click)="retrySource()">Повторить</button>
        </mat-card>
        <mat-card class="slot">
          <mat-card-title>Эталонный макет</mat-card-title>
          <input type="file" (change)="onRefFile($event)" />
          <mat-progress-bar *ngIf="refProgress > 0" [value]="refProgress"></mat-progress-bar>
          <p *ngIf="refError" class="error">{{ refError }}</p>
          <button mat-button *ngIf="refError" (click)="retryRef()">Повторить</button>
        </mat-card>
        <button mat-raised-button [disabled]="!canCreate" (click)="create()">Создать заявку</button>
      </div>
    </div>
  `
})
export class Scr002Component {
  private api = inject(ApiService);
  private router = inject(Router);
  state: 'empty' | 'loading' | 'error' | 'forbidden' | 'success' = 'empty';
  sourceProgress = 0; refProgress = 0;
  sourceError = ''; refError = '';
  sourceFile: File | null = null; refFile: File | null = null;
  sourceFileId = ''; refFileId = '';
  type = 'photo';

  get canCreate() { return !!this.sourceFileId && !!this.refFileId; }

  onSourceFile(e: Event) { this.uploadFile(e, 'source'); }
  onRefFile(e: Event) { this.uploadFile(e, 'reference'); }

  private uploadFile(e: Event, role: string) {
    const input = e.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) return;
    const fileType = file.type.includes('png') ? 'png' : file.type.includes('jpeg') ? 'jpeg' : 'mp4';
    this.api.getUploadUrl(fileType, role, file.size).subscribe({
      next: (res) => {
        if (role === 'source') { this.sourceFile = file; this.sourceFileId = res.file_id; this.sourceProgress = 100; }
        else { this.refFile = file; this.refFileId = res.file_id; this.refProgress = 100; }
        this.api.confirmFileUpload(res.file_id).subscribe();
      },
      error: (err) => {
        if (role === 'source') this.sourceError = 'Ошибка загрузки';
        else this.refError = 'Ошибка загрузки';
      }
    });
  }

  retrySource() { this.sourceError = ''; }
  retryRef() { this.refError = ''; }
  login() { /* TODO */ }
  create() {
    this.api.createApplication({ type: this.type as any, reference_file_id: this.refFileId, source_file_id: this.sourceFileId }).subscribe({
      next: (app) => this.router.navigate(['/status', app.id]),
      error: () => this.state = 'error'
    });
  }
}

import { Component, inject, OnInit, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { MatButtonModule } from '@angular/material/button';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { ApiService, Application } from '../../services/api.service';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-scr-003',
  standalone: true,
  imports: [CommonModule, MatButtonModule, MatProgressSpinnerModule],
  template: `
    <div class="scr-003">
      <div *ngIf="state === 'forbidden'" class="center">
        <p>Требуется авторизация</p>
        <button mat-button (click)="login()">Войти</button>
      </div>
      <div *ngIf="state === 'loading'" class="center">
        <mat-spinner></mat-spinner>
        <p>Анализ медиафайла…</p>
        <p>Поиск рекламного блока…</p>
        <p>Нарезка видео…</p>
      </div>
      <div *ngIf="state === 'error'" class="center">
        <p>Не удалось обработать файл</p>
        <button mat-button (click)="retry()">Повторить обработку</button>
        <button mat-button (click)="back()">Вернуться к загрузке</button>
      </div>
      <div *ngIf="state === 'success'" class="center">
        <p>Выполнено</p>
        <button mat-raised-button (click)="toResults()">Посмотреть результаты</button>
      </div>
    </div>
  `
})
export class Scr003Component implements OnInit, OnDestroy {
  private api = inject(ApiService);
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private sub?: Subscription;
  private timer?: any;
  state: 'empty' | 'loading' | 'error' | 'forbidden' | 'success' = 'loading';
  app?: Application;
  id = '';

  ngOnInit() {
    this.id = this.route.snapshot.paramMap.get('id') || '';
    if (!this.id) { this.router.navigate(['/']); return; }
    this.poll();
  }

  ngOnDestroy() { this.sub?.unsubscribe(); clearInterval(this.timer); }

  private poll() {
    this.sub = this.api.getApplication(this.id).subscribe({
      next: (app) => {
        this.app = app;
        if (app.status === 'completed') this.state = 'success';
        else if (app.status === 'failed') this.state = 'error';
      },
      error: (err) => {
        if (err.status === 401) this.state = 'forbidden';
        else if (err.status === 404) this.router.navigate(['/']);
        else this.state = 'error';
      }
    });
    this.timer = setInterval(() => this.poll(), 5000);
  }

  retry() { this.state = 'loading'; this.api.triggerProcessing(this.id).subscribe(); }
  back() { this.router.navigate(['/upload']); }
  toResults() { this.router.navigate(['/results', this.id]); }
  login() { /* TODO */ }
}

import { Routes } from '@angular/router';
import { Scr001Component } from './screens/scr-001/scr-001.component';
import { Scr002Component } from './screens/scr-002/scr-002.component';
import { Scr003Component } from './screens/scr-003/scr-003.component';

export const routes: Routes = [
  { path: '', component: Scr001Component },
  { path: 'upload', component: Scr002Component },
  { path: 'status/:id', component: Scr003Component },
  { path: '**', redirectTo: '' }
];
